for n in range(90,108):
 r=rs[n-1];print("JSONL line",n,{k:r.get(k) for k in ks})
print("steps 97-150 aggregate")
for k in ks:
 vs=[r[k] for r in rs[96:] if isinstance(r.get(k),(int,float))]
 if vs: print(k,"min",min(vs),"max",max(vs),"unique",len(set(vs)))
print("reward zero run",all(r["critic/score/mean"]==0 for r in rs[96:]),"pg loss zero run",all(r["actor/pg_loss"]==0 for r in rs[96:]))
print("val rows")
for r in rs:
 if "val-core/openai/gsm8k/acc/mean@1" in r: print(r["console_step"],{k:v for k,v in r.items() if k.startswith("val-") or k.startswith("timing_s/test") or k.startswith("timing_s/save")})'

