arguments.command:
python -I -c 'import json,math
for name in ("console-history.jsonl","wandb-history.jsonl"):
 rs=[json.loads(x) for x in open("/workspace/observed_run/"+name)]
 print(name,"records",len(rs))
 bad=[]; strings=[]
 for i,r in enumerate(rs,1):
  for k,v in r.items():
   if isinstance(v,float) and not math.isfinite(v): bad.append((i,k,v))
   if isinstance(v,str): strings.append((i,k,v))
 print("nonfinite",bad)
 print("strings",strings)
 print("epoch values",sorted(set(r.get("training/epoch") for r in rs)))
 print("lr values",sorted(set(r.get("actor/lr") for r in rs)))
 print("global steps sequential",[r.get("training/global_step") for r in rs]==list(range(1,len(rs)+1)))
 print("aborted unique",sorted(set(r.get("response/aborted_ratio") for r in rs)))
 print("clip nonzero first/last",next((r.get("console_step",r.get("_step")) for r in rs if r.get("response_length/clip_ratio",0)>0),None),[r.get("console_step",r.get("_step")) for r in rs if r.get("response_length/clip_ratio",0)>0][-1])'

